{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "There is limited evidence to evaluate the sustainability of evidence-based interventions (EBIs) for healthcare improvement.",
      "reason": "The background states the current state of knowledge (limited evidence) regarding evaluating EBI sustainability."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Through an integrative review, we aimed to identify approaches to evaluate the sustainability of evidence-based interventions (EBIs) and sustainability outcomes.",
      "reason": "The rationale for conducting the review is explained via the stated review aim to identify evaluation approaches and sustainability outcomes."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PARTIAL",
      "chunk_id": "text_20",
      "quote": "A focus on evaluation is what differentiates this review from recent syntheses published on approaches to sustainability research. In a review by Lennox et al., they indicated that only 21% of studies reported any information on sustainability outcomes [6].",
      "reason": "The manuscript references prior syntheses (e.g., Lennox et al.) and states differentiation from recent syntheses, but it does not clearly explain the specific need for a current review in terms of updates/replications of a named prior systematic review."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No proposed mechanism of action of an intervention is described in the retrieved evidence; the rationale focuses on evaluating sustainability rather than specifying intervention mechanisms."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not provide a logic model for hypothesised relationships between intervention components and outcomes."
    }
  ],
  "confidence": 62
}

