{
  "item_id": "PRISMA_2020_10a",
  "elements": [
    {
      "element_id": "prisma_2020_10a_e1",
      "status": "PARTIAL",
      "chunk_id": "text_12",
      "quote": "We extracted whether an included study evaluated (a) sustainability determinants and (b) sustainability outcomes and how they measured these variables. We defined sustainability determinants as correlates and predictors of sustainability (organizational, contextual, and strategies) and sustainability outcomes as the subsequent impact (healthcare improvement or public health outcomes) of sustained intervention use [5]. To further unpack sustainability outcomes, we extracted and synthesized nine sustainability outcomes across the 64 included studies (Table 3) [6, 15, 16].",
      "reason": "The review states outcome-related domains (sustainability determinants and sustainability outcomes) and provides definitions; however, it does not clearly enumerate/define all outcome domains beyond these constructs (e.g., the full set of outcome domains and how each domain was defined/structured for data extraction is not fully specified)."
    },
    {
      "element_id": "prisma_2020_10a_e2",
      "status": "PRESENT",
      "chunk_id": "text_19",
      "quote": "Of 64 included studies, 66% ( n = 43) [20, 22, 24, 25, 28, 31, 34, 35, 39-42, 44, 45, 48-59, 63, 65-76, 79-82] had a clear timing for evaluation and 33% ( n = 21) [19, 21, 23, 26, 27, 29, 30, 32, 33, 36-38, 43, 46, 47, 60-62, 64, 77, 78] had unclear timing. Of the 43 studies with clear timing, 42% ( n = 18) evaluated sustainability at a single time point ... The remaining 57% ( n = 25) evaluated sustainability at multiple time points ... The majority of studies (63%; n = 40) conducted data collection post evaluation only ... Evaluation timing and data collection time points are provided in Table 9.",
      "reason": "The time frame/timing of evaluation and data collection (single vs multiple time points; post-evaluation only vs other timing) is reported, with details summarized and referenced to Table 9."
    },
    {
      "element_id": "prisma_2020_10a_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No statement was found indicating whether all compatible results within each outcome domain were sought."
    },
    {
      "element_id": "prisma_2020_10a_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "There is no evidence that the authors did not seek all compatible results, and no description of any process used to select results."
    },
    {
      "element_id": "prisma_2020_10a_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No changes to outcome-domain inclusion/definitions/importance (with rationales) are reported in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_10a_e6",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No changes to processes for selecting results within outcome domains (with rationales) are reported in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_10a_e7",
      "status": "PARTIAL",
      "chunk_id": "text_19",
      "quote": "Whether or not benefits continued for patients, staff, and stakeholders was the most commonly evaluated outcome of sustainability ( n = 45). The next most reported outcomes are the capacity built within staff stakeholders, and communities ( n = 29), and adaptations made in response to new evidence or contextual influences ( n = 29).",
      "reason": "The evidence identifies which outcomes were most commonly evaluated (useful for interpreting conclusions), but it does not provide an explicit rationale for prioritising these outcomes beyond frequency."
    }
  ],
  "confidence": 58
}

